const sd=$getWorkflowStaticData('global');
let trig='schedule', cf='', fp=false;
// Door 1: Execute Workflow call (Manual Start) with clientFilter / fullPass in its payload.
try{
  const t=$('Manual Start').first().json||{};
  trig='event';
  const b=(t&&typeof t.body==='object'&&t.body)?t.body:{};
  const q=(t&&typeof t.query==='object'&&t.query)?t.query:{};
  cf=String(t.clientFilter||b.clientFilter||q.clientFilter||'').trim();
  const rawFp=(t.fullPass!==undefined?t.fullPass:(b.fullPass!==undefined?b.fullPass:q.fullPass));
  fp=(rawFp===true||String(rawFp).toLowerCase()==='true');
}catch(e){}
// Door 2: Hub launch row (Run Context). Its Client link becomes the filter; trigger = form.
const launch=sd.launch||{};
if(launch.recordId){ trig='form'; cf=String(launch.clientFilter||cf||'').trim(); }
sd.run={start:$now.toISO(), trigger:trig, clientFilter:cf, fullPass:fp};
sd.clients={};
sd.pull=null;
sd.write=null;
return [{json:{trigger:trig, clientFilter:cf, fullPass:fp}}];

const sd=$getWorkflowStaticData('global');
const cfRaw=String((sd.run||{}).clientFilter||'').trim();
const cf=cfRaw.toLowerCase();
// The filter is either a Clients record id (from a Hub launch row) or a name fragment (from a manual call).
const byId=/^rec[a-z0-9]{14}$/i.test(cfRaw);
const out=[];
for(const it of $input.all()){
  const r=it.json||{};
  const f=r.fields||r;
  const name=String(f['Client name']||f['Client']||'').trim();
  const ws=String(f['PlusVibe Workspace ID']||'').trim();
  const crBase=String(f['Clayroots Base ID']||'').trim();
  if(!r.id||!name||!ws||!crBase) continue;
  if(cf && (byId ? r.id!==cfRaw : name.toLowerCase().indexOf(cf)===-1)) continue;
  out.push({json:{clientRecId:r.id, clientName:name, ws, crBase}});
}
// Nothing to loop over: emit one placeholder so the Any Clients? gate can route straight to the run log.
if(!out.length) return [{json:{_empty:true}}];
return out;

const sd=$getWorkflowStaticData('global');
const id=sd.currentClient;
const c=sd.clients[id];
const cids=Object.keys(c.perCampaign);
let complete=0;
for(const cid of cids){ const p=c.perCampaign[cid]; const ok=(p.sentCounter===null||p.sentCounter===undefined)||Number(p.sumSentStep)===Number(p.sentCounter)||p.accepted===true; if(ok) complete++; }
const rowsWritten=Object.keys(c.updates).reduce((s,t)=>s+(c.updates[t]||0),0);
const skips=c.skippedTables.map(s=>'table skipped: '+s);
if(c.nominated===0) skips.push('no nominated leads, nothing to write');
const warns=c.warnings.slice();
for(const t of Object.keys(c.goneTables||{})) warns.push('table gone mid-run: '+t+' ('+c.goneTables[t]+' batches skipped)');
c.summary={name:c.name, mode:(c.watermark?('incremental since '+c.watermark):'backfill'), campaigns:cids.length, complete, incomplete:cids.length-complete, leadsPulled:c.leadsPulled, nominated:c.nominated, rowsWritten, failedList:[].concat(c.errors, c.invariant), warnings:warns, skips, pullOk:c.pullOk!==false, writeOk:c.writeOk!==false};
delete c.perCampaign; delete c.payloads; delete c.updates; delete c.errors; delete c.warnings; delete c.invariant; delete c.skippedTables; delete c.targetTables; delete c.mirrorMap; delete c._noMirrorWarned; delete c.goneTables;
sd.write=null;
sd.pull={queue:[], idx:0, byCampaign:{}};
return [{json:{clientRecId:id}}];

const sd=$getWorkflowStaticData('global');
const ch=(sd.write&&sd.write.current)||{};
const c=sd.clients[ch.clientRecId];
const isGone=s=>/INVALID_PERMISSIONS_OR_MODEL_NOT_FOUND|TABLE_NOT_FOUND|NOT_FOUND|MODEL_ID_NOT_FOUND/i.test(s);
const recs=[];
for(const it of $input.all()){
  const j=it.json||{};
  if(Array.isArray(j.records)) recs.push(...j.records);
  else if(j.error){
    const s=JSON.stringify(j.error).slice(0,300);
    if(isGone(s)){ c.goneTables[ch.tableName]=(c.goneTables[ch.tableName]||0)+1; }
    else { c.errors.push('list '+ch.tableName+': '+s.slice(0,200)); c.writeOk=false; }
  }
}
const norm=e=>String(e||'').toLowerCase().trim();
const patches=[];
for(const r of recs){
  const em=norm((r.fields||{})['Final Email']);
  const p=c.payloads[em];
  if(!p) continue;
  const fields={'Messages Sent':p['Messages Sent'], 'Campaign Status':p['Campaign Status'], 'Bounce Reason':p['Bounce Reason'], 'Synced At':p['Synced At']};
  if(p['Last Contacted']) fields['Last Contacted']=p['Last Contacted'];
  if(c.mirrorId){
    const links=[];
    for(const cid of (p['Campaigns']||[])){
      const rid=(c.mirrorMap||{})[cid];
      if(rid) links.push(rid);
      else if(!c._noMirrorWarned[cid]){ c._noMirrorWarned[cid]=1; c.warnings.push('no mirror row for campaign '+cid+'; Campaigns link skipped for its leads'); }
    }
    fields['Campaigns']=links;
  }
  patches.push({id:r.id, fields});
}
const out=[];
for(let i=0;i<patches.length;i+=10){
  out.push({json:{crBase:ch.crBase, tableId:ch.tableId, tableName:ch.tableName, clientRecId:ch.clientRecId, body:{records:patches.slice(i,i+10), typecast:true}}});
}
if(!out.length) return [{json:{_none:true}}];
return out;

const sd=$getWorkflowStaticData('global');
const ch=(sd.write&&sd.write.current)||{};
const c=sd.clients[ch.clientRecId];
const isGone=s=>/INVALID_PERMISSIONS_OR_MODEL_NOT_FOUND|TABLE_NOT_FOUND|NOT_FOUND|MODEL_ID_NOT_FOUND/i.test(s);
try{
  for(const it of $('Patch Records').all()){
    const j=it.json||{};
    if(Array.isArray(j.records)) c.updates[ch.tableName]=(c.updates[ch.tableName]||0)+j.records.length;
    else if(j.error){
      const s=JSON.stringify(j.error).slice(0,300);
      if(isGone(s)){ c.goneTables[ch.tableName]=(c.goneTables[ch.tableName]||0)+1; }
      else { c.errors.push('patch '+ch.tableName+': '+s.slice(0,200)); c.writeOk=false; }
    }
  }
}catch(e){}
return [{json:{done:true}}];

const sd=$getWorkflowStaticData('global');
const c=$input.first().json;
sd.currentClient=c.clientRecId;
sd.pull={queue:[], idx:0, page:1, attempts:0, got:0, retried:false, byCampaign:{}, campStart:0};
sd.write={queue:[], idx:0, current:null};
sd.clients[c.clientRecId]={name:c.clientName, ws:c.ws, crBase:c.crBase, startedAt:Date.now(), watermark:null, leadsPulled:0, nominated:0, perCampaign:{}, payloads:{}, targetTables:[], skippedTables:[], mirrorId:'', mirrorMap:{}, _noMirrorWarned:{}, fieldsCreated:0, updates:{}, errors:[], warnings:[], invariant:[], invariantOk:true, pullOk:true, writeOk:true, goneTables:{}};
return [{json:c}];

const sd=$getWorkflowStaticData('global');
const c=sd.clients[sd.currentClient];
let wm=null;
if(!((sd.run||{}).fullPass)){
  try{
    const r=$input.first().json||{};
    const f=r.fields||r;
    const ra=f['Run at'];
    if(r.id&&ra){ const d=new Date(ra); if(!isNaN(d.getTime())) wm=new Date(d.getTime()-24*3600*1000).toISOString(); }
  }catch(e){}
}
c.watermark=wm;
return [{json:{clientRecId:sd.currentClient, watermark:wm, ws:c.ws}}];

const sd=$getWorkflowStaticData('global');
const c=sd.clients[sd.currentClient];
const raw=[];
let sawValidEmpty=false;
let firstSnippet='';
for(const it of $input.all()){
  const j=it.json||{};
  const hasWrap=Object.prototype.hasOwnProperty.call(j,'body');
  const body=hasWrap?j.body:j;
  const status=Number(j.statusCode||0);
  if(!firstSnippet) firstSnippet=JSON.stringify(hasWrap?{statusCode:status, body:body}:j).slice(0,300);
  const ok=!status||(status>=200&&status<300);
  const arr=Array.isArray(body)?body:(body&&Array.isArray(body.campaigns)?body.campaigns:(body&&Array.isArray(body.data)?body.data:((body&&(body.id||body._id))?[body]:null)));
  if(ok&&Array.isArray(arr)){
    for(const x of arr){ if(x&&(x.id||x._id)) raw.push(x); }
    if(!arr.length) sawValidEmpty=true;
  }
  if(hasWrap&&status>=200&&status<300&&body&&typeof body==='object'&&!Array.isArray(body)&&!Object.keys(body).length) sawValidEmpty=true;
}
if(!raw.length){
  if(sawValidEmpty) c.warnings.push('workspace has no campaigns');
  else { c.errors.push('campaign/list-all failed or unrecognized response - failing closed. First response item: '+firstSnippet); c.pullOk=false; }
}
const out=[];
for(const x of raw){
  const id=String(x.id||x._id);
  c.perCampaign[id]={name:x.camp_name||x.name||id, sentCounter:Number(x.sent_count||0), sumSentStep:0, leads:0};
  out.push({json:{campaign_id:id, ws:c.ws, expected:(x.lead_count===undefined||x.lead_count===null)?null:Number(x.lead_count)}});
}
if(!out.length) return [{json:{_none:true}}];
return out;

const sd=$getWorkflowStaticData('global');
const c=sd.clients[sd.currentClient];
const inFirst=($input.first()||{}).json||{};
const leads=[];
if(!inFirst._none){
  const P=sd.pull||{};
  const by=P.byCampaign||{};
  for(const k of Object.keys(by)){
    for(const l of by[k]){
      if(!l||!(l.email||l.lead_email)) continue;
      leads.push(Object.assign({}, l, {campaign_id:String(l.campaign_id||k)}));
    }
  }
}
const wm=c.watermark?new Date(c.watermark).getTime():null;
const norm=e=>String(e||'').toLowerCase().trim();
const groups={};
let kept=0;
for(const l of leads){
  const em=norm(l.email||l.lead_email); if(!em) continue;
  const cid=String(l.campaign_id||'');
  if(!c.perCampaign[cid]) continue;
  kept++;
  const rec={cid, status:String(l.status||'').toUpperCase(), sent_step:Number(l.sent_step||0), last_sent_at:l.last_sent_at||null, modified_at:l.modified_at||null, replied_count:Number(l.replied_count||0), bounce_msg:String(l.bounce_msg||'')};
  c.perCampaign[cid].sumSentStep+=rec.sent_step;
  c.perCampaign[cid].leads++;
  (groups[em]=groups[em]||[]).push(rec);
}
c.leadsPulled=kept;
const prec={UNSUBSCRIBED:6,BOUNCED:5,REPLIED:4,IN_SEQUENCE:3,COMPLETED:2,NEVER_CONTACTED:1};
const mapStatus=s=>{ if(s==='UNSUBSCRIBED')return 'UNSUBSCRIBED'; if(s==='BOUNCED')return 'BOUNCED'; if(s==='REPLIED')return 'REPLIED'; if(s==='CONTACTED'||s==='PENDING'||s==='RESCHEDULED')return 'IN_SEQUENCE'; if(s==='COMPLETED')return 'COMPLETED'; return 'NEVER_CONTACTED'; };
const runStart=(sd.run||{}).start||$now.toISO();
let nominated=0;
for(const em of Object.keys(groups)){
  const recs=groups[em];
  const nom = wm===null || recs.some(r=> (r.modified_at && new Date(r.modified_at).getTime()>wm) || r.status==='REPLIED' || r.status==='UNSUBSCRIBED');
  if(!nom) continue;
  nominated++;
  let sent=0, last=null, worst='NEVER_CONTACTED', bm='', bmTs=-1;
  const cids=[];
  for(const r of recs){
    sent+=r.sent_step;
    if(r.last_sent_at){ const t=new Date(r.last_sent_at).getTime(); if(!isNaN(t)&&(last===null||t>last)) last=t; }
    const m=mapStatus(r.status); if(prec[m]>prec[worst]) worst=m;
    if(r.bounce_msg){ const t=r.modified_at?new Date(r.modified_at).getTime():0; if(t>=bmTs){ bmTs=t; bm=r.bounce_msg; } }
    if(!cids.includes(r.cid)) cids.push(r.cid);
  }
  c.payloads[em]={'Messages Sent':sent, 'Last Contacted': last===null?null:new Date(last).toISOString(), 'Campaign Status':worst, 'Bounce Reason':bm, 'Campaigns':cids, 'Synced At':runStart};
}
c.nominated=nominated;
const ACCEPTED={'6a5e3dc49b872335dfa3f027':{sum:364, sent:365}, '6a3ad9db3b32b093822e07fb':{sum:1783, sent:1387}, '6a3ad9daf294f74388ea65ac':{sum:4034, sent:3127}};
for(const cid of Object.keys(c.perCampaign)){
  const p=c.perCampaign[cid];
  if(p.sentCounter===null||p.sentCounter===undefined) continue;
  if(Number(p.sumSentStep)===Number(p.sentCounter)) continue;
  const acc=ACCEPTED[cid];
  if(acc && Number(p.sumSentStep)===acc.sum && Number(p.sentCounter)===acc.sent){
    p.accepted=true;
    c.warnings.push('known mismatch (accepted): '+p.name+' '+p.sumSentStep+' vs '+p.sentCounter);
  } else if(acc){
    c.invariantOk=false;
    c.invariant.push(p.name+' ('+cid+'): sum sent_step='+p.sumSentStep+' vs campaign sent='+p.sentCounter+' - DRIFTED beyond accepted '+acc.sum+' vs '+acc.sent);
  } else {
    c.invariantOk=false;
    c.invariant.push(p.name+' ('+cid+'): sum sent_step='+p.sumSentStep+' vs campaign sent='+p.sentCounter);
  }
}
if(sd.pull) sd.pull.byCampaign={};
return [{json:{clientRecId:sd.currentClient, crBase:c.crBase, nominated}}];

const sd=$getWorkflowStaticData('global');
const c=sd.clients[sd.currentClient];
const j=($input.first()||{}).json||{};
const tables=Array.isArray(j.tables)?j.tables:[];
if(!tables.length){ c.errors.push('schema fetch failed or base has no tables'); c.writeOk=false; return [{json:{_none:true}}]; }
const mirror=tables.find(t=>{ const names=new Set((t.fields||[]).map(f=>f.name)); return !names.has('Final Email') && names.has('Campaign ID') && names.has('Sequencer'); });
c.mirrorId=mirror?mirror.id:'';
const want=[
 {name:'Messages Sent', spec:{name:'Messages Sent', type:'number', options:{precision:0}}},
 {name:'Last Contacted', spec:{name:'Last Contacted', type:'dateTime', options:{dateFormat:{name:'iso'}, timeFormat:{name:'24hour'}, timeZone:'utc'}}},
 {name:'Campaign Status', spec:{name:'Campaign Status', type:'singleSelect', options:{choices:[{name:'NEVER_CONTACTED'},{name:'IN_SEQUENCE'},{name:'COMPLETED'},{name:'REPLIED'},{name:'BOUNCED'},{name:'UNSUBSCRIBED'}]}}},
 {name:'Bounce Reason', spec:{name:'Bounce Reason', type:'singleLineText'}},
 {name:'Synced At', spec:{name:'Synced At', type:'dateTime', options:{dateFormat:{name:'iso'}, timeFormat:{name:'24hour'}, timeZone:'utc'}}}
];
const out=[];
for(const t of tables){
  const fe=(t.fields||[]).find(f=>f.name==='Final Email');
  if(!fe) continue;
  if(fe.type!=='singleLineText' && fe.type!=='email'){ c.skippedTables.push(t.name+' (Final Email is '+fe.type+')'); continue; }
  c.targetTables.push({id:t.id, name:t.name});
  c.updates[t.name]=0;
  const have=new Set((t.fields||[]).map(f=>f.name));
  for(const w of want){ if(!have.has(w.name)) out.push({json:{tableId:t.id, tableName:t.name, field:w.spec}}); }
  if(mirror && !have.has('Campaigns')) out.push({json:{tableId:t.id, tableName:t.name, field:{name:'Campaigns', type:'multipleRecordLinks', options:{linkedTableId:mirror.id}}}});
}
if(!c.targetTables.length){ c.errors.push('no target tables with Final Email found in base'); c.writeOk=false; }
if(!mirror) c.warnings.push('no campaigns mirror table (Campaign ID + Sequencer fields, no Final Email); Campaigns link field skipped');
if(!out.length) return [{json:{_none:true}}];
return out;

const sd=$getWorkflowStaticData('global');
const c=sd.clients[sd.currentClient];
const inFirst=($input.first()||{}).json||{};
if(!inFirst._none){
  try{
    const res=$('Create Fields').all();
    let ok=0;
    for(const it of res){ const j=it.json||{}; if(j.id) ok++; else if(j.error){ c.errors.push('field create: '+JSON.stringify(j.error).slice(0,200)); c.writeOk=false; } }
    c.fieldsCreated=ok;
  }catch(e){}
}
const emails=Object.keys(c.payloads);
sd.write={queue:[], idx:0, current:null};
for(const t of c.targetTables){
  for(let i=0;i<emails.length;i+=100){
    const slice=emails.slice(i,i+100);
    const formula='OR('+slice.map(e=>'LOWER(TRIM({Final Email}))="'+e.replace(/"/g,'')+'"').join(',')+')';
    sd.write.queue.push({clientRecId:sd.currentClient, crBase:c.crBase, tableId:t.id, tableName:t.name, formula, emails:slice.length});
  }
}
return [{json:{clientRecId:sd.currentClient, chunks:sd.write.queue.length, mirrorId:c.mirrorId||'', crBase:c.crBase}}];

const sd=$getWorkflowStaticData('global');
const items=$input.all().map(i=>i.json).filter(x=>x&&x.campaign_id);
sd.pull={queue:items.map(x=>({id:String(x.campaign_id), ws:x.ws, expected:(x.expected===undefined?null:x.expected)})), idx:0, page:1, attempts:0, got:0, retried:false, byCampaign:{}, campStart:Date.now()};
if(!sd.pull.queue.length) return [{json:{done:true, wait:0}}];
const f=sd.pull.queue[0];
return [{json:{ws:f.ws, campaign_id:f.id, page:1, wait:0}}];

const sd=$getWorkflowStaticData('global');
const P=sd.pull;
const c=sd.clients[sd.currentClient];
const j=($input.first()||{}).json||{};
const cur=P.queue[P.idx];
const emit=o=>[{json:o}];
const advance=()=>{ P.idx++; P.page=1; P.attempts=0; P.got=0; P.retried=false; P.campStart=Date.now(); if(P.idx<P.queue.length){ const n=P.queue[P.idx]; return emit({ws:n.ws, campaign_id:n.id, page:1, wait:2}); } return emit({done:true, wait:0}); };
if(Date.now()-(P.campStart||Date.now())>900000){
  c.errors.push('time-box: campaign '+cur.id+' exceeded 15 minutes, aborted (page '+P.page+', '+P.got+' leads pulled)');
  c.pullOk=false;
  return advance();
}
const hasWrap=Object.prototype.hasOwnProperty.call(j,'body');
const body=hasWrap?j.body:j;
const status=Number(j.statusCode||0);
let arr=null;
if(Array.isArray(body)) arr=body;
else if(body&&Array.isArray(body.data)) arr=body.data;
else if(body&&Array.isArray(body.leads)) arr=body.leads;
if(status&&(status<200||status>=300)) arr=null;
const nextReq=w=>emit({ws:cur.ws, campaign_id:cur.id, page:P.page, wait:w});
if(arr===null){
  P.attempts++;
  if(P.attempts<=5){
    let w=Math.pow(2,P.attempts);
    const h=j.headers||{};
    const ra=Number(h['retry-after']||h['Retry-After']||0);
    if(ra>0) w=Math.max(w,Math.min(ra,120));
    return nextReq(w);
  }
  c.errors.push('lead pull failed: campaign '+cur.id+' page '+P.page+' after 5 retries (status '+(status||'?')+'): '+JSON.stringify(body).slice(0,200));
  c.pullOk=false;
  return advance();
}
P.attempts=0;
(P.byCampaign[cur.id]=P.byCampaign[cur.id]||[]).push(...arr);
P.got+=arr.length;
if(arr.length===100){
  P.page++;
  if(P.page>500){ c.errors.push('lead pull aborted: campaign '+cur.id+' exceeded 500 pages'); c.pullOk=false; return advance(); }
  return nextReq(2);
}
if(cur.expected!==null&&cur.expected!==undefined&&Number(P.got)!==Number(cur.expected)){
  if(!P.retried){ P.retried=true; P.page=1; P.got=0; P.attempts=0; P.byCampaign[cur.id]=[]; return nextReq(3); }
  c.errors.push('pull-completeness: campaign '+cur.id+' pulled '+P.got+' of expected '+cur.expected+' after full campaign retry');
  c.pullOk=false;
}
return advance();

const sd=$getWorkflowStaticData('global');
const W=sd.write||{queue:[], idx:0};
if(W.idx<W.queue.length){ W.current=W.queue[W.idx]; W.idx++; return [{json:Object.assign({done:false}, W.current)}]; }
W.current=null;
return [{json:{done:true}}];

const sd=$getWorkflowStaticData('global');
const c=sd.clients[sd.currentClient];
c.mirrorMap={};
for(const it of $input.all()){
  const r=it.json||{};
  const f=r.fields||r;
  const cid=String(f['Campaign ID']||'').trim();
  if(cid&&r.id) c.mirrorMap[cid]=r.id;
}
return [{json:{mapped:Object.keys(c.mirrorMap).length}}];

const sd=$getWorkflowStaticData('global');
const run=sd.run||{};
const durS=Math.round((Date.now()-new Date(run.start||Date.now()).getTime())/1000);
const clients=Object.keys(sd.clients||{}).map(id=>sd.clients[id]);
let totalIn=0, totalOut=0, failedClients=0;
const allFailed=[], skipLines=[], warnLines=[], clientLines=[], wmHold=[];
for(const c of clients){
  const s=c.summary||{};
  totalIn+=s.leadsPulled||0;
  totalOut+=s.rowsWritten||0;
  const fl=s.failedList||[];
  if(fl.length) failedClients++;
  for(const e of fl) allFailed.push('**'+(s.name||'?')+':** '+e);
  for(const sk of (s.skips||[])) skipLines.push('**'+(s.name||'?')+':** '+sk);
  for(const w of (s.warnings||[])) warnLines.push('**'+(s.name||'?')+':** '+w);
  if(s.pullOk===false) wmHold.push((s.name||'?')+' pull incomplete');
  if(s.writeOk===false) wmHold.push((s.name||'?')+' write failures');
  clientLines.push('- **'+(s.name||'?')+':** '+[(s.campaigns||0)+' campaigns ('+(s.complete||0)+'/'+(s.campaigns||0)+' invariants OK)', (s.leadsPulled||0)+' leads pulled', (s.nominated||0)+' refreshed', (s.rowsWritten||0)+' rows written', s.mode||''].filter(Boolean).join(' · '));
}
const partial=!!(run.clientFilter);
if(partial) wmHold.push('partial run (clientFilter "'+run.clientFilter+'")');
const wmOk=wmHold.length===0 && clients.length>0;
const md=[];
md.push('**'+clients.length+' clients, '+failedClients+' failed**');
md.push('');
md.push('**Watermark:** '+(wmOk?'advanced (pull complete, writes clean)':('HELD - '+wmHold.join('; '))));
md.push('');
md.push('**Clients**');
for(const l of clientLines) md.push(l);
if(allFailed.length){ md.push(''); md.push('**FAILED ('+allFailed.length+')**'); for(const e of allFailed) md.push('- '+e); }
if(skipLines.length){ md.push(''); md.push('**Skipped ('+skipLines.length+')**'); for(const e of skipLines) md.push('- '+e); }
if(warnLines.length){ md.push(''); md.push('**Warnings ('+warnLines.length+')**'); for(const e of warnLines) md.push('- '+e); }
const errTotal=allFailed.length;
sd.clients={};
const row={
  'Automation':'Sync PlusVibe Leads to Clayroots',
  'Status':errTotal?'Succeeded with errors':'Succeeded',
  'Watermark OK':wmOk,
  'Trigger':run.trigger||'event',
  'Run at':run.start||new Date().toISOString(),
  'Duration s':durS,
  'Records In':totalIn,
  'Records Out':totalOut,
  'Errors':errTotal,
  'Execution ID':String($execution.id),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Description':md.join('\n').slice(0,95000)
};
// Client is attached only when the run served exactly one client (a record-id filter); never an empty link array.
if(/^rec[a-z0-9]{14}$/i.test(String(run.clientFilter||''))) row['Client']=[run.clientFilter];
return [{json:row}];

// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd=$getWorkflowStaticData('global');
let launch=null;
try{ const r=$('Fetch Launch Record').first().json; if(r&&r.id) launch=r; }catch(e){}
const f=(launch&&launch.fields)||launch||{};
const cl=Array.isArray(f.Client)&&f.Client.length?f.Client[0]:'';
const clientFilter=(cl&&typeof cl==='object')?String(cl.id||''):String(cl||'');
sd.launch={ recordId: launch?String(launch.id):'', trigger: launch?'form':'schedule', clientFilter, startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];
